HEAD='<!doctype html>\n<html lang="ru" data-l="ru">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">\n<meta name="description" content="Коммерческое предложение по ускорению и продвижению raycorral.com / Proposal to speed up and promote raycorral.com">\n<meta name="robots" content="noindex">\n<title>Ray Corral: редизайн</title>\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;600&family=Golos+Text:wght@400;500;600&display=swap">\n<style>\n/* Layout: proposal document, one 880px column; full-width bands for evidence (filmstrips); tessera squares mark status and stages. */\n:root{\n  --bg:#EEF0F2; --surface:#FFFFFF; --fg:#1B2230; --muted:#5A6476; --line:#D5DAE1;\n  --cobalt:#1F4BB0; --cobalt-soft:#E1E8F7;\n  --good:#2F7D5B; --good-soft:#E2F1E9; --bad:#B23A3A; --bad-soft:#F6E2E2; --warn:#A8661A;\n  --ink-band:#151A23; --ink-band-fg:#E7EAF0;\n  --display:"Cormorant Garamond","Times New Roman",Georgia,serif;\n  --body:"Golos Text",system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;\n}\n@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){\n  --bg:#12161D; --surface:#1A2029; --fg:#E7EAF0; --muted:#9AA4B5; --line:#2C3441;\n  --cobalt:#7EA2F2; --cobalt-soft:#1E2A44; --good:#6CC59C; --good-soft:#18302A; --bad:#EE8080; --bad-soft:#3A1E22; --warn:#E0A55C;\n  --ink-band:#0B0E13; --ink-band-fg:#E7EAF0; color-scheme:dark}}\n:root[data-theme="dark"]{\n  --bg:#12161D; --surface:#1A2029; --fg:#E7EAF0; --muted:#9AA4B5; --line:#2C3441;\n  --cobalt:#7EA2F2; --cobalt-soft:#1E2A44; --good:#6CC59C; --good-soft:#18302A; --bad:#EE8080; --bad-soft:#3A1E22; --warn:#E0A55C;\n  --ink-band:#0B0E13; --ink-band-fg:#E7EAF0; color-scheme:dark}\n\n*{box-sizing:border-box}\nhtml[data-l="ru"] .en, html[data-l="en"] .ru{display:none!important}\nbody{background:var(--bg);color:var(--fg);font-family:var(--body);font-size:17px;line-height:1.6}\n.pad{padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px))}\n.wrap{max-width:880px;margin:0 auto}\nh1,h2,h3{font-family:var(--display);font-weight:600;line-height:1.08;text-wrap:balance;margin:0}\nh1{font-size:clamp(2.5rem,7vw,4.2rem)}\nh2{font-size:clamp(1.9rem,4.5vw,2.6rem)}\nh3{font-size:1.4rem}\np{margin:0}\n.eyebrow{font-size:.76rem;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);font-weight:600}\n.lead{font-size:1.12rem;max-width:64ch}\n.muted{color:var(--muted)}\n.note{font-size:.86rem;color:var(--muted)}\na{color:var(--cobalt)}\nsection{padding-block:60px;border-top:1px solid var(--line)}\nsection > .wrap{display:grid;gap:20px}\n\n/* top bar */\n.bar{position:sticky;top:env(safe-area-inset-top,0px);z-index:5;background:var(--bg);border-bottom:1px solid var(--line)}\nbody::before{content:"";position:fixed;inset:0 0 auto;height:env(safe-area-inset-top,0px);z-index:10;background:var(--bg)}\n.bar .wrap{display:flex;align-items:center;justify-content:space-between;gap:12px;padding-block:10px}\n.brand{font-family:var(--display);font-size:1.25rem;font-weight:600}\n.lang{display:inline-flex;border:1px solid var(--line);border-radius:99px;padding:3px;background:var(--surface)}\n.lang button{all:unset;cursor:pointer;font-size:.82rem;font-weight:600;padding:5px 14px;border-radius:99px;color:var(--muted)}\n.lang button[aria-pressed="true"]{background:var(--cobalt);color:#fff}\n.lang button:focus-visible{outline:2px solid var(--cobalt);outline-offset:2px}\n\n/* hero */\nheader.hero{padding-block:56px 48px}\nheader.hero .wrap{display:grid;gap:22px}\n.tiles{display:grid;grid-template-columns:repeat(14,12px);gap:4px}\n.tiles i{width:12px;height:12px;border-radius:2px;background:var(--cobalt);opacity:.15}\n.tiles i:nth-child(3n){opacity:.45}.tiles i:nth-child(5n){opacity:.85}.tiles i:nth-child(7n){opacity:.3}\n.meta{display:flex;flex-wrap:wrap;gap:8px 22px;font-size:.88rem;color:var(--muted)}\n.meta b{color:var(--fg);font-weight:600}\n\n/* key numbers */\n.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px}\n.kpi{background:var(--surface);border:1px solid var(--line);border-radius:6px;padding:16px 18px;display:grid;gap:6px;align-content:start}\n.kpi .v{font-family:var(--display);font-size:2.1rem;font-weight:600;line-height:1;font-variant-numeric:tabular-nums}\n.kpi .v small{font-family:var(--body);font-size:.8rem;font-weight:600;color:var(--good);margin-left:6px;vertical-align:middle}\n.kpi .from{font-size:.85rem;color:var(--muted);font-variant-numeric:tabular-nums}\n.kpi .l{font-size:.92rem}\n\n/* film strips (dark band) */\n.band{background:var(--ink-band);color:var(--ink-band-fg);border-top:0}\n.band .eyebrow,.band .muted,.band .note{color:#9AA4B5}\n.film{display:grid;gap:10px}\n.film .row{display:grid;grid-template-columns:96px 1fr;gap:12px;align-items:center}\n.film .tag{font-size:.8rem;font-weight:600;letter-spacing:.06em;text-transform:uppercase}\n.tag.b{color:#EE8080}.tag.a{color:#6CC59C}\n.frames{display:grid;gap:8px;min-width:0}\n.frames.d{grid-template-columns:repeat(4,minmax(0,1fr))}\n.frames.m{grid-template-columns:repeat(4,minmax(0,1fr));max-width:560px}\nfigure{margin:0;display:grid;gap:4px}\nfigure img{width:100%;height:auto;display:block;border-radius:4px;border:1px solid #2C3441}\nfigcaption{font-size:.76rem;color:#9AA4B5;font-variant-numeric:tabular-nums}\n.timeax{display:grid;grid-template-columns:96px 1fr;gap:12px}\n@media (max-width:600px){\n  .film .row{grid-template-columns:1fr}\n  .timeax{display:none}\n  .frames.d{grid-template-columns:repeat(2,minmax(0,1fr))}\n}\n.callout{border-left:3px solid #6CC59C;padding:2px 0 2px 14px;font-size:.95rem;max-width:68ch}\n\n/* findings */\n.find{display:grid;gap:16px}\n.f{display:grid;grid-template-columns:12px 1fr;gap:14px}\n.f::before{content:"";width:12px;height:12px;border-radius:2px;margin-top:.5em;background:var(--bad)}\n.f.w::before{background:var(--warn)}\n.f > div{min-width:0;display:grid;gap:4px}\n.f p{color:var(--muted);font-size:.95rem}\n\n/* hover proof */\n.proof{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}\n.proof figure img{border-color:var(--line)}\n.proof figcaption{color:var(--muted)}\n\n/* table */\n.tbl{overflow-x:auto;background:var(--surface);border:1px solid var(--line);border-radius:6px}\ntable{border-collapse:collapse;width:100%;font-size:.92rem;font-variant-numeric:tabular-nums}\nth,td{text-align:left;padding:10px 14px;border-bottom:1px solid var(--line);white-space:nowrap}\ntr:last-child td{border-bottom:0}\nth{font-size:.78rem;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);font-weight:600}\ntd.g{color:var(--good);font-weight:600}\ntd.grp{font-weight:600;background:var(--cobalt-soft);color:var(--cobalt)}\n\n/* stages */\n.stages{display:grid;gap:14px}\n.st{background:var(--surface);border:1px solid var(--line);border-radius:6px;padding:20px 22px;display:grid;gap:10px}\n.st .hd{display:flex;align-items:baseline;gap:14px;flex-wrap:wrap}\n.st .n{font-family:var(--display);font-size:2rem;color:var(--cobalt);line-height:1}\n.chip{margin-left:auto;font-size:.8rem;font-weight:600;padding:3px 10px;border-radius:99px;background:var(--cobalt-soft);color:var(--cobalt)}\n.chip.done{background:var(--good-soft);color:var(--good)}\n.price{font-family:var(--display);font-size:1.6rem;font-weight:600;font-variant-numeric:tabular-nums;white-space:nowrap}\n.price small{font-family:var(--body);font-size:.8rem;color:var(--muted);font-weight:500}\n.st .hd .chip{margin-left:0}\n.st .hd .price{margin-left:auto}\n.btns{display:flex;flex-wrap:wrap;gap:10px}\n.btn{display:inline-flex;align-items:center;gap:8px;padding:11px 18px;border-radius:6px;font-weight:600;font-size:.95rem;text-decoration:none;border:1px solid var(--line);color:var(--fg);background:var(--surface)}\n.btn.primary{background:var(--cobalt);border-color:var(--cobalt);color:#fff}\n.btn:focus-visible{outline:2px solid var(--cobalt);outline-offset:2px}\n.btn::after{content:"↗";font-weight:400}\n.side{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}\n.side figure img{border-color:var(--line)}\n.side figcaption{color:var(--muted);font-size:.86rem}\n@media (max-width:600px){.side{grid-template-columns:1fr}}\n.sum td:last-child,.sum th:last-child{text-align:right}\n.sum td:first-child{white-space:normal;min-width:240px}\n.sum tr.total td{font-weight:600;background:var(--good-soft);color:var(--good)}\n.sum s{color:var(--muted);font-weight:400;margin-right:8px}\n.opts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}\n@media (max-width:700px){.opts{grid-template-columns:1fr}}\n.opt{background:var(--surface);border:1px solid var(--line);border-radius:6px;padding:22px;display:grid;gap:12px;align-content:start}\n.opt.rec{border:2px solid var(--cobalt)}\n.opt .badge{justify-self:start;font-size:.78rem;font-weight:600;padding:3px 10px;border-radius:99px;background:var(--cobalt);color:#fff}\n.opt .pr{display:flex;align-items:baseline;gap:12px;flex-wrap:wrap}\n.opt ul{margin:0;padding-left:1.1em;display:grid;gap:5px;font-size:.95rem}\n.shots{display:grid;grid-template-columns:2fr 2fr 1fr;gap:12px;align-items:start}\n.shots figure img{border:1px solid var(--line);border-radius:4px}\n.shots figcaption{color:var(--muted);font-size:.84rem}\n@media (max-width:700px){.shots{grid-template-columns:1fr 1fr}.shots figure:last-child{grid-column:1/-1;max-width:220px}}\n.vs{display:grid;gap:clamp(28px,4vw,48px)}\n.vs-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}\n.vs-row figure img{border:1px solid var(--line);border-radius:4px}\n.vs-row figcaption{font-size:.88rem;color:var(--muted)}\n.vs-row figcaption b{color:var(--fg);font-weight:600}\n.vs-head{display:flex;align-items:baseline;gap:12px;grid-column:1/-1}\n.vs-head h3{font-size:1.5rem}\n.lbl{font-size:.72rem;font-weight:600;letter-spacing:.08em;text-transform:uppercase;padding:2px 8px;border-radius:99px}\n.lbl.now{background:var(--bad-soft);color:var(--bad)}.lbl.new{background:var(--good-soft);color:var(--good)}\n@media (max-width:600px){.vs-row{grid-template-columns:1fr}}\n.cmp td{white-space:normal;vertical-align:top;min-width:150px}\n.cmp td:first-child{font-weight:600;min-width:130px}\n.cmp td.new{color:var(--good)}\n.kept{display:flex;flex-wrap:wrap;gap:8px}\n.kept span{border:1px solid var(--line);border-radius:99px;padding:5px 12px;font-size:.88rem;background:var(--surface)}\n.divider{display:flex;align-items:center;gap:14px}\n.divider::after{content:"";flex:1;height:1px;background:var(--line)}\n.st ul{margin:0;padding-left:1.1em;display:grid;gap:5px}\n.st .res{border-top:1px dashed var(--line);padding-top:9px;font-size:.94rem}\n.st .res b{color:var(--good)}\n\n.guar{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}\n.guar div{border-left:3px solid var(--cobalt);padding:2px 0 2px 14px;display:grid;gap:4px}\n.guar p{font-size:.92rem;color:var(--muted)}\nfooter{padding-block:36px 60px;border-top:1px solid var(--line);font-size:.86rem;color:var(--muted)}\ncode{font-size:.9em}\n</style>\n<style>body{margin:0}img{max-width:100%}</style>\n</head>\n<body>\n\n<div class="bar pad"><div class="wrap">\n  <span class="brand">Ray Corral · raycorral.com</span>\n  <div class="lang" role="group" aria-label="Language">\n    <button type="button" id="btn-ru" data-set="ru" aria-pressed="true">RU</button>\n    <button type="button" id="btn-en" data-set="en" aria-pressed="false">EN</button>\n  </div>\n</div></div>\n\n'
FIND='<section class="pad"><div class="wrap">\n  <span class="eyebrow"><span class="ru">Что мешает сейчас</span><span class="en">What gets in the way today</span></span>\n  <h2><span class="ru">Почему сайт медленный</span><span class="en">Why the site is slow</span></h2>\n  <div class="find">\n    <div class="f"><div><strong><span class="ru">Одни и те же библиотеки грузятся по два-три раза</span><span class="en">The same libraries load two or three times</span></strong>\n      <p><span class="ru">Анимационная библиотека подключена дважды, рядом её версия 2017 года, плавная прокрутка тоже в двух копиях. Телефон делает лишнюю работу на каждом заходе.</span><span class="en">The animation library is included twice, plus its 2017 version, and smooth scrolling also comes in two copies. The phone does extra work on every visit.</span></p></div></div>\n    <div class="f"><div><strong><span class="ru">Анимированный фон создавался трижды</span><span class="en">The animated background was created three times</span></strong>\n      <p><span class="ru">Две версии библиотеки Unicorn Studio и проект, указанный дважды, давали три 3D-сцены на 60 кадрах в секунду, в том числе на телефонах.</span><span class="en">Two versions of the Unicorn Studio library and a project referenced twice produced three 3D scenes at 60 fps, phones included.</span></p></div></div>\n    <div class="f"><div><strong><span class="ru">Скрипт с чужого учебного сайта</span><span class="en">A script loaded from a third-party demo site</span></strong>\n      <p><span class="ru">Эффект «волны» на фото подгружался с демонстрационной страницы постороннего ресурса вместе с 3D-движком 2019 года. На главной этот эффект работал на скрытом блоке, который никто не видит.</span><span class="en">The photo “ripple” effect was loaded from an unrelated demo page together with a 3D engine from 2019. On the home page it ran on a hidden block nobody can see.</span></p></div></div>\n    <div class="f w"><div><strong><span class="ru">Фото тяжелее, чем нужно</span><span class="en">Photos are heavier than needed</span></strong>\n      <p><span class="ru">Телефону отправляются снимки под большой монитор, а главная фотография грузится последней. Из 6 МБ главной страницы около 5,4 МБ приходится на фото.</span><span class="en">Phones receive images sized for large monitors, and the main photo loads last. About 5.4 MB of the 6 MB home page is photography.</span></p></div></div>\n    <div class="f w"><div><strong><span class="ru">Google почти не видит работы</span><span class="en">Google barely sees the work</span></strong>\n      <p><span class="ru">Нет карты сайта, у фото нет подписей, у внутренних страниц нет описаний, два адреса с опечатками (philantropy, miditerranean), сайт открывается и с www, и без.</span><span class="en">No sitemap, no image descriptions, no page descriptions, two URLs with typos (philantropy, miditerranean), and the site answers on both www and non-www.</span></p></div></div>\n  </div>\n</div></section>\n\n\n'
PROMO='<section class="pad"><div class="wrap">\n  <span class="eyebrow"><span class="ru">Продвижение</span><span class="en">Promotion</span></span>\n  <h2><span class="ru">Продвижение статьями</span><span class="en">Promotion through articles</span></h2>\n  <p class="lead"><span class="ru">Заказчики мозаики премиум-класса долго выбирают: ищут примеры, читают о технике и стилях, сравнивают мастерские. Статьи приводят их на сайт из Google по точным запросам и сразу показывают уровень Рэя. Каждая статья работает годами, в отличие от рекламы.</span><span class="en">Premium mosaic clients take their time: they look for examples, read about technique and styles, compare studios. Articles bring them to the site from Google on precise queries and show Ray’s level right away. Each article keeps working for years, unlike ads.</span></p>\n  <div class="opt"><ul><li><span class="ru">Подбор поисковых запросов и план тем: по каким словам ищут заказчики мозаики (custom mosaic pool, Art Deco mosaic, hand-cut glass mosaic и т.д.)</span><span class="en">Keyword research and a topic plan: what mosaic clients actually search for (custom mosaic pool, Art Deco mosaic, hand-cut glass mosaic and more)</span></li><li><span class="ru">Статьи-истории проектов: задача, стиль, материалы, техника, фото процесса; каждая ведёт в страницу проекта</span><span class="en">Project story articles: brief, style, materials, technique, process photos; each one leads to the project page</span></li><li><span class="ru">Экспертные статьи от имени Рэя: как выбрать мозаику для бассейна, чем ручная резка стекла отличается от фабричной плитки, история стилей, уход за мозаикой</span><span class="en">Expert articles in Ray’s name: choosing a pool mosaic, hand-cut glass versus factory tile, the history of styles, caring for mosaic</span></li><li><span class="ru">Публикации в профильных и lifestyle-изданиях: гостевые статьи и интервью со ссылкой на сайт, развитие колонки в Forbes Councils</span><span class="en">Placements in trade and lifestyle media: guest articles and interviews linking to the site, building on the Forbes Councils column</span></li><li><span class="ru">Оптимизация каждой статьи под Google: заголовок, описание, подписи к фото, ссылки на проекты и контакты</span><span class="en">Each article optimized for Google: title, description, image text, links to projects and contact</span></li><li><span class="ru">Блок «О нас писали» на сайте с цитатами изданий</span><span class="en">An “As featured in” block on the site with press quotes</span></li></ul></div>\n</div></section>\n\n'
FOOT='<footer class="pad"><div class="wrap">\n  <span class="ru">Подготовлено по публичной версии raycorral.com 10 ноября 2026 года. Код редизайна и сырые замеры: </span><span class="en">Based on the public version of raycorral.com, 10 November 2026. Redesign code and raw measurements: </span><a href="https://github.com/Dirol982/raycorral">github.com/Dirol982/raycorral</a>\n</div></footer>\n\n<script>\n(function () {\n  var root = document.documentElement;\n  var titles = { ru: \'Ray Corral: редизайн\', en: \'Ray Corral: redesign\' };\n  function set(l) {\n    root.setAttribute(\'data-l\', l);\n    root.setAttribute(\'lang\', l);\n    document.title = titles[l];\n    document.querySelectorAll(\'[data-set]\').forEach(function (b) { b.setAttribute(\'aria-pressed\', String(b.getAttribute(\'data-set\') === l)); });\n    try { localStorage.setItem(\'kp-lang\', l); } catch (e) {}\n  }\n  var initial = location.hash === \'#en\' ? \'en\' : location.hash === \'#ru\' ? \'ru\' : null;\n  if (!initial) { try { initial = localStorage.getItem(\'kp-lang\'); } catch (e) {} }\n  set(initial === \'en\' ? \'en\' : \'ru\');\n  document.querySelectorAll(\'[data-set]\').forEach(function (b) {\n    b.addEventListener(\'click\', function () { set(b.getAttribute(\'data-set\')); });\n  });\n  window.addEventListener(\'hashchange\', function () { if (location.hash === \'#en\' || location.hash === \'#ru\') set(location.hash.slice(1)); });\n})();\n</script>\n\n</body>\n</html>\n'
